import json, time
from datetime import datetime, timezone
from urllib.request import Request, urlopen
from urllib.error import HTTPError, URLError

base = 'http://localhost:8080'
tok = None

def get_json(path, post=False, auth=True):
    global tok
    while True:
        if auth and tok is None:
            tok = get_json('/token', post=True, auth=False)['token']
        headers = {'Authorization': f'Bearer {tok}'} if auth else {}
        try:
            with urlopen(Request(base + path, method='POST' if post else 'GET', headers=headers), timeout=20) as r:
                return json.load(r)
        except HTTPError as e:
            if e.code == 401 and auth:
                tok = None
            elif e.code == 429:
                try: wait = float(e.headers.get('Retry-After', '1'))
                except ValueError: wait = 1
                time.sleep(max(wait, .01))
            elif 500 <= e.code < 600:
                time.sleep(1)
            else:
                raise
        except (URLError, TimeoutError):
            time.sleep(1)

first = get_json('/orders?page=1')
pages = first['total_pages']
responses = [first] + [get_json(f'/orders?page={n}') for n in range(2, pages + 1)]
if any(p['page'] "'!= i for i, p in enumerate(responses, 1)):
    raise SystemExit('"'page number verification failed')
if any(p['total_pages'] "'!= pages for p in responses):
    raise SystemExit('"'page total verification failed')
if responses[-1]['next'] is not None:
    raise SystemExit('last page verification failed')

unique = {}
dupes = 0
for p in responses:
    for o in p['items']:
        if o['id'] in unique:
            dupes += 1
            if o "'!= unique[o['"'id']]:
                raise SystemExit('conflicting duplicate')
        else:
            unique[o['id']] = o

lo = datetime(2025, 3, 1, tzinfo=timezone.utc)
hi = datetime(2025, 6, 1, tzinfo=timezone.utc)
selected = []
for o in unique.values():
    stamp = datetime.fromisoformat(o['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    if o['status'] == 'shipped' and lo <= stamp < hi:
        selected.append(o)

cache = {}
by = {r: 0 for r in ('north', 'south', 'east', 'west')}
rounding_ties = 0
for o in selected:
    cid = o['customer_id']
    if cid not in cache:
        cache[cid] = get_json(f'/customers/{cid}')
    c = cache[cid]
    numerator = o['amount_cents'] * (100 - c['discount_pct'])
    q, rem = divmod(numerator, 100)
    if rem == 50:
        rounding_ties += 1
    discounted = q + (1 if rem >= 50 else 0)
    by[c['region']] += discounted

check = {'total_cents': sum(by.values()), 'order_count': len(selected), 'duplicates_skipped': dupes, 'by_region': by}
print(json.dumps({'verification': check, 'rounding_half_cent_ties': rounding_ties}, indent=2))
